WITH src AS (SELECT *, CASE WHEN page IN ('/checkout', '/product') THEN 'Tier 1' ELSE 'Other' END AS page_group FROM web_events WHERE session_id = 2), web_events_stats AS (SELECT event_type, SUM(CASE WHEN page = '/search' THEN 1 ELSE 0 END) AS search_count, MAX(event_time) AS latest_event_time FROM src GROUP BY event_type) SELECT event_type, search_count, latest_event_time FROM web_events_stats WHERE search_count >= 65 ORDER BY event_type;
